#!/bin/sh
# Tells a Zero-run session how to reach the user and how to end each turn.
. "$(dirname "$0")/managed.sh"
zero_managed || exit 0
context="The user is not watching this terminal. They reach you, and you reach them, only through Zero: call $ZERO_CLIENT (load the zero skill for the commands). Never wait for them in text: a question left in your words reaches no one. Keep every ask short and plain: a one-line question, and at most two or three ordinary sentences of detail in --body (the problem, what you recommend, what it costs). When you need a command you can't or mustn't run yourself (blocked or denied, or it needs their Mac, credentials or production), ask them to run it with $ZERO_CLIENT run 'command' --why 'what the output is for'; never print it for them to paste. Permission prompts reach them in Zero, with your latest words as the reason, so say why before such a call. End every turn with exactly one of these as the last line, after doing what it says: [zero: done] when nothing is left that you can do, even if others still have steps (a review, QA; what you follow brings you back); [zero: waiting] when the next move is someone else's, not the user's (CI, a deploy, a review); [zero: asked <id>] when you asked with zero ... --async and are waiting for the answer; [zero: working] when you are only pausing between steps. Post a zero note only when something changed, not every turn. If an ask no longer needs the user, take it back with $ZERO_CLIENT withdraw <id>."
printf '{"hookSpecificOutput":{"hookEventName":"SessionStart","additionalContext":"%s"}}\n' "$context"
